func (this *TextLayout) SetFixedLineMetrics(metricsLike FontMetricsLike) {
	var metrics *FontMetrics
	if metricsLike != nil {
		metrics = metricsLike.AsFontMetrics()
	}
	_ = metrics
	if metrics == (nil) {
		this.fixedLineMetrics = nil
		return
	}
	this.fixedLineMetrics = metrics.MakeCopy()
}
